</template>
<script setup>
import{computed,onMounted,ref}from"vue";import BioNexusFormField from"@/components/ui/BioNexusFormField.vue";import BioNexusActionIcon from"@/components/ui/BioNexusActionIcon.vue";import BioNexusIcon from"@/components/ui/BioNexusIcon.vue";import{getTypePayments}from"@/services/typePaymentService";import{getCurrentDollarValue}from"@/services/dollarValueService";import{closePatientAdmission,patientAdmissionError}from"@/services/patientAdmissionService";import{formatRegionalMoney,formatUsdPrice}from"@/services/regionalFormatter";import{useRegionalSettingsStore}from"@/stores/regionalSettings";import{useAuthorizationStore}from"@/stores/authorization";
